body:
Hello, Andrii

I just finished looking at your code and noticed that in uds_tp_isotp, especially in receiving and sending SF and FF, it currently only supports the default classic CAN mode and doesn't support CANFD mode.

1. The code is as follows, this is SF's receiving  code
static void uds_rx_sf(uds_isotp_ctx_t *iso, struct uds_ctx *uds, const uint8_t *data, uint8_t len)
{
    /* Abort any active multi-frame on new Single Frame */
    iso->state = ISOTP_IDLE;

    uint8_t sdu_len = (uint8_t) (data[0] & 0x0Fu);
    uint8_t data_offset = 1;

    if (sdu_len == 0u) {
        /* CAN-FD SF: Byte 0 is 0x00, Byte 1 is Length */
        if (len < 2u) return; /* Not enough data for the FD length byte */
        sdu_len = data[1];
        data_offset = 2;
        if (sdu_len == 0) return; /* Invalid */
    }

    if (sdu_len > (len - data_offset)) {
        /* Not enough data in frame */
        return;
    }

    uds_input_sdu(uds, &data[data_offset], (uint16_t) sdu_len);
}

<img width="1311" height="720" alt="Image" src="https://github.com/user-attachments/assets/12cc5d9b-51bb-4a09-ae1a-fca08af401a7" />

But in the ISO15765 standard, the reception of a single-frame SF is as follows

<img width="1734" height="948" alt="Image" src="https://github.com/user-attachments/assets/a7f640b2-f4cf-4d22-b01b-fc061b0b5903" />
Your SF single-frame reception code only handles the classic 8-byte CAN reception and ignores the 64-byte CAN FD reception. You need to add that.

2. The code is as follows, this is SF's send code

static int uds_send_sf(uds_isotp_ctx_t *iso, const uint8_t *data, uint16_t len)
{
    uint8_t frame[ISOTP_MAX_DL_CANFD] = {0};
    uint8_t dl = ISOTP_MAX_DL_CAN;

    if (len <= ISOTP_SF_MAX_DL_CAN) {
        /* Standard SF: [PCI+DL] [Data...] */
        frame[0] = (uint8_t) ((uint8_t) ISOTP_PCI_SF | (uint8_t) len);
        memcpy(&frame[1], data, len);
        dl = ISOTP_MAX_DL_CAN;
    }
    else {
        /* CAN-FD SF: [00] [DL] [Data...] */
        frame[0] = ISOTP_PCI_SF;  /* 0x00 */
        frame[1] = (uint8_t) len; /* Data Length */
        memcpy(&frame[2], data, len);
        /* Calculate valid DLC for FD */
        dl = uds_dlc_align(len + 2);
    }

    return uds_internal_tp_send_frame(iso, frame, dl);
}
<img width="1308" height="702" alt="Image" src="https://github.com/user-attachments/assets/b8529937-8f3d-45f9-8c67-fb2bd1f3c6af" />

It looks like you're sending single-frame SF, and you've considered both classic CAN and CANFD at the same time, no problem.

<img width="1686" height="840" alt="Image" src="https://github.com/user-attachments/assets/e862c1b0-ec26-4115-8ac5-771de629d2d3" />

3. The code is as follows, this is First frame FF's receiving  code

static void uds_rx_ff(uds_isotp_ctx_t *iso, struct uds_ctx *uds, const uint8_t *data, uint8_t len)
{
    /* Abort any active multi-frame on new First Frame */
    iso->state = ISOTP_IDLE;

    if (len < 2u) {
        return; /* FF requires at least PCI + length byte */
    }

    uint16_t sdu_len =
        (uint16_t) ((uint16_t) ((uint16_t) data[0] & 0x0Fu) << 8u) | (uint16_t) data[1];
    if (sdu_len < 8u) {
        return; /* Multi-frame must be > 7 bytes (Standard) or handled by SF */
    }

    iso->msg_len = sdu_len;

    /* Determine data in FF */
    uint8_t data_in_ff;
    if (len > ISOTP_MAX_DL_CAN) {
        /* CAN-FD FF */
        data_in_ff = len - 2;
    }
    else {
        /* Classic CAN FF */
        data_in_ff = ISOTP_FF_MAX_DATA_CAN;
    }

    iso->bytes_processed = data_in_ff;
    iso->sn = 1;
    iso->state = ISOTP_RX_WAIT_CF;
    iso->timer_n_cr = uds->config->get_time_ms ? uds->config->get_time_ms() : 0u;

    if (uds->config->rx_buffer_size < sdu_len) {
        iso->state = ISOTP_IDLE;
        return;
    }
    memcpy(uds->config->rx_buffer, &data[2], data_in_ff);

    /* Send Flow Control (CTS) */
    uint8_t fc[8] = {0};
    fc[0] = (uint8_t) (ISOTP_PCI_FC | ISOTP_FC_CTS);
    fc[1] = iso->block_size;
    fc[2] = iso->st_min;
    uds_internal_tp_send_frame(iso, fc, 8);
}

<img width="1566" height="885" alt="Image" src="https://github.com/user-attachments/assets/9d5f750d-7dfc-49bf-8d29-e5e85a6ec7e9" />

<img width="1479" height="900" alt="Image" src="https://github.com/user-attachments/assets/f548d839-86f3-4e42-8cf3-f8b6222c26f0" />

<img width="1758" height="870" alt="Image" src="https://github.com/user-attachments/assets/72227e24-6a17-4f6e-bdce-d46053e90549" />

Just like with receiving single-frame SFs, you only considered handling the first frame FF for the classic 8-byte CAN and ignored the 64-byte CAN FD handling. I hope you can add CAN FD first frame FF reception handling, it's really important.


4. The code is as follows, this is First frame FF's send code
static int uds_send_mf(uds_isotp_ctx_t *iso, const uint8_t *data, uint16_t len)
{
    if (len > ISOTP_MAX_SDU_LEN_STD || len > iso->tx_sdu_size) {
        return -2;
    }

    memcpy(iso->tx_sdu_buf, data, len);
    iso->tx_sdu_len = len;

    iso->msg_len = len;
    iso->bytes_processed = 0;
    iso->state = ISOTP_TX_WAIT_FC;
    iso->timer_n_bs = 0u; /* armed on the first process() tick in WAIT_FC */

    uint8_t frame[ISOTP_MAX_DL_CANFD] = {0};
    uint8_t dl = ISOTP_MAX_DL_CAN;

    /* FF Header: [1n] [nn] */
    frame[0] = (uint8_t) ((uint8_t) ISOTP_PCI_FF | (uint8_t) ((len >> 8u) & 0x0Fu));
    frame[1] = (uint8_t) (len & 0xFFu);

    uint8_t max_data_in_ff = (iso->use_can_fd) ? ISOTP_FF_MAX_DATA_CANFD : ISOTP_FF_MAX_DATA_CAN;

    /* Copy as much as fits in FF */
    uint8_t to_copy = (len > max_data_in_ff) ? max_data_in_ff : (uint8_t) len;
    memcpy(&frame[2], data, to_copy);

    iso->bytes_processed = to_copy;
    iso->sn = 1u;

    if (iso->use_can_fd) {
        dl = uds_dlc_align(2 + to_copy);
    }
    else {
        dl = ISOTP_MAX_DL_CAN;
    }

    if (uds_internal_tp_send_frame(iso, frame, dl) != 0) {
        return -1;
    }

    return 0; /* Multi-Frame started successfully */
}

<img width="1374" height="812" alt="Image" src="https://github.com/user-attachments/assets/2f6687f5-b640-41aa-8a5b-7356bc4d245a" />

<img width="1446" height="825" alt="Image" src="https://github.com/user-attachments/assets/a976d0a1-e7dc-40bb-90b2-bdcfa6e4d205" />

You only added the case when the FF first frame receives less than 4095 bytes, but you ignored the case when the FF first frame is larger than 4095 bytes. This is something you need to add. Especially during CANFD large data transmission, this is really useful for doing UDS OTA upgrades.

<img width="1665" height="627" alt="Image" src="https://github.com/user-attachments/assets/c904fb89-7345-4690-a3fe-070e3faf0015" />

5. Your flow control frame FC reception ignores handling of two states, overflow and wait. I hope you can add them.
static void uds_rx_fc(uds_isotp_ctx_t *iso, const uint8_t *data, uint8_t len)
{
    if (iso->state != ISOTP_TX_WAIT_FC) {
        return;
    }
    if (len < 3u) {
        return; /* FC requires flow status, block size and STmin */
    }

    uint8_t fs = data[0] & 0x0F;
    if (fs == ISOTP_FC_CTS) {
        iso->state = ISOTP_TX_SENDING_CF;
        iso->block_size = data[1];
        iso->st_min = data[2];
        iso->timer_n_bs = 0u; /* FC arrived: disarm N_Bs */
    }
}

